<script setup lang="ts">
import {ref,onMounted} from 'vue'
import api from '@/api/client'
import ConsoleDialog from '@/components/ConsoleDialog.vue'
interface Num {sid:string;phone_number:string;friendly_name:string;capabilities:{voice:boolean;sms:boolean}}
interface Review {number:string;connections:string[];blocked:boolean;fingerprint:string}
const numbers=ref<Num[]>([]),accounts=ref<{number:string;username:string;state:string}[]>([]),error=ref(''),notice=ref(''),loading=ref(false)
const review=ref<Review|null>(null),checking=ref(false),choosing=ref(false),confirmed=ref(false),saving=ref(false)
function errorText(e:unknown,fallback:string){return (e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||fallback}
async function load(){loading.value=true;error.value='';try{const [n,a]=await Promise.all([api.get('/business/numbers'),api.get('/business/accounts')]);numbers.value=n.data.data;accounts.value=a.data.data}catch{error.value='Could not fetch owned Twilio numbers'}finally{loading.value=false}}
function assigned(n:string){return accounts.value.find(a=>a.number===n)}
function usable(n:Num){return n.capabilities.voice&&n.capabilities.sms}
async function inspect(number:string,choose=false){checking.value=true;error.value='';notice.value='';confirmed.value=false;choosing.value=choose;try{review.value=(await api.get('/business/number-review',{params:{number},timeout:60000})).data}catch(e){error.value=errorText(e,'Could not check this number’s connections. No changes were made.')}finally{checking.value=false}}
async function choose(){if(!review.value||review.value.blocked||!confirmed.value)return;saving.value=true;error.value='';try{await api.put('/business/phone-number',{number:review.value.number,number_review:review.value.fingerprint},{timeout:150000});notice.value=`The phone now uses ${review.value.number}.`;review.value=null;await load()}catch(e){error.value=errorText(e,'The number could not be assigned. The previous number is kept.')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="space-y-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold">Phone numbers</h1><p class="text-sm text-gray-500 mt-2">Numbers owned by your Twilio account. Choose which one the phone uses for calls and SMS.</p></div><button @click="load" :disabled="loading" class="border rounded px-4 py-2">Refresh from Twilio</button></div><p v-if="error" role="alert" class="text-red-600">{{error}}</p><p v-if="notice" role="status" class="text-green-500">{{notice}}</p><div class="bg-white dark:bg-gray-800 rounded-lg overflow-x-auto"><table class="responsive-table min-w-full text-left text-sm"><thead><tr><th class="p-4">Number</th><th class="p-4">Voice / SMS</th><th class="p-4">Phone</th><th class="p-4">Actions</th></tr></thead><tbody><tr v-for="n in numbers" :key="n.sid" class="border-t"><td data-label="Number" class="p-4">{{n.phone_number}}<p class="text-gray-500">{{n.friendly_name}}</p></td><td data-label="Voice / SMS" class="p-4">{{n.capabilities.voice?'Voice':'No voice'}} · {{n.capabilities.sms?'SMS':'No SMS'}}</td><td data-label="Phone" class="p-4"><template v-if="assigned(n.phone_number)"><span class="font-medium">In use by {{assigned(n.phone_number)?.username}}</span><p class="text-gray-500">{{assigned(n.phone_number)?.state}}</p></template><span v-else class="text-gray-500">Not used</span></td><td data-label="Actions" class="p-4"><div class="flex flex-wrap gap-3"><button v-if="!assigned(n.phone_number)&&usable(n)" @click="inspect(n.phone_number,true)" :disabled="checking||saving" class="text-primary">Use for phone</button><button @click="inspect(n.phone_number)" :disabled="checking||saving" class="text-primary" :aria-label="`Check connections for ${n.phone_number}`">Check connections</button></div></td></tr><tr v-if="!loading&&!numbers.length"><td colspan="4" class="p-6 text-gray-500">No numbers found in this Twilio account.</td></tr></tbody></table></div>
<ConsoleDialog v-if="review" :label="choosing?'Use this number for the phone':'Number connections'" @close="!saving&&(review=null)"><div class="space-y-4"><h2 class="text-xl font-semibold">{{choosing?'Use '+review.number+' for the phone?':'Connections for '+review.number}}</h2><p class="text-sm">Existing connections detected:</p><ul class="list-disc pl-5 text-sm break-all"><li v-for="c in review.connections" :key="c">{{c}}</li><li v-if="!review.connections.length">No webhook, application, Messaging Service or local route was detected.</li></ul><template v-if="choosing"><p class="text-sm">This replaces the number's voice/SMS webhooks so calls and SMS reach the phone. Other services connected to it may stop receiving calls or SMS. The previous number keeps its Twilio webhooks but no longer rings the phone.</p><p v-if="review.blocked" role="alert" class="text-amber-500">Blocked: this number uses a Messaging Service inbound handler. Change that in Twilio first.</p><label v-else class="flex items-start gap-2"><input v-model="confirmed" type="checkbox" class="mt-1"/>I reviewed these connections and want the phone to use this number.</label></template><p v-else class="text-sm text-gray-500">Read-only check. Nothing was changed.</p><div class="dialog-actions"><button @click="review=null" :disabled="saving" class="border rounded px-4 py-2">{{choosing?'Cancel':'Close'}}</button><button v-if="choosing" @click="choose" :disabled="saving||review.blocked||!confirmed" class="bg-primary text-white rounded px-4 py-2">{{saving?'Assigning…':'Use this number'}}</button></div></div></ConsoleDialog></div></template>
